{
  "mechanisms": [
    {
      "name": "load_dependent_wm_decay",
      "title": "Load-Dependent WM Decay",
      "description": "Working memory weights decay toward a uniform distribution on every trial, with the decay rate increasing as a function of set size for set sizes greater than 3.",
      "params": [
        {
          "name": "load_scale",
          "bounds": [0, null]
        }
      ],
      "evidence": "load_term = max(0.0, (nS - 3))\nwm_decay = np.clip(load_scale * (load_term / max(1.0, nS)), 0.0, 1.0)\n...\nw = (1.0 - wm_decay) * w + wm_decay * w_0",
      "expressible_in_slots": true
    },
    {
      "name": "surprise_gated_wm_arbitration",
      "title": "Surprise-Gated WM Arbitration",
      "description": "The probability of relying on working memory increases when the absolute reward prediction error (surprise) is high.",
      "params": [
        {
          "name": "wm_base",
          "bounds": [null, null]
        },
        {
          "name": "surprise_gain",
          "bounds": [0, null]
        }
      ],
      "evidence": "surprise = abs(r - Q_s[a])\nwm_logit = wm_base + surprise_gain * surprise - load_scale * load_term\nwm_weight = 1.0 / (1.0 + np.exp(-wm_logit))",
      "expressible_in_slots": true
    },
    {
      "name": "load_dependent_wm_arbitration",
      "title": "Load-Dependent WM Arbitration",
      "description": "The probability of relying on working memory decreases as the set size (load) increases beyond a threshold of 3.",
      "params": [
        {
          "name": "load_scale",
          "bounds": [0, null]
        }
      ],
      "evidence": "wm_logit = wm_base + surprise_gain * surprise - load_scale * load_term\nwm_weight = 1.0 / (1.0 + np.exp(-wm_logit))",
      "expressible_in_slots": true
    },
    {
      "name": "arbitration_scaled_wm_encoding",
      "title": "Arbitration-Scaled WM Encoding",
      "description": "The learning rate for working memory on rewarded trials is scaled by the current arbitration weight for working memory.",
      "params": [
        {
          "name": "wm_learn",
          "bounds": [0, 1]
        }
      ],
      "evidence": "eta = wm_learn * wm_weight\nw[s, :] = (1.0 - eta) * w[s, :] + eta * target",
      "expressible_in_slots": true
    },
    {
      "name": "smoothed_wm_target",
      "title": "Smoothed WM Target",
      "description": "On rewarded trials, the working memory target distribution is smoothed, assigning partial probability to unchosen actions rather than being strictly one-hot.",
      "params": [],
      "evidence": "target = w_0[s, :].copy()\ntarget[a] = 1.0\ntarget = target / np.sum(target)",
      "expressible_in_slots": true
    },
    {
      "name": "negative_feedback_wm_diffusion",
      "title": "Negative-Feedback WM Diffusion",
      "description": "On unrewarded trials, working memory weights diffuse toward a uniform distribution rather than updating toward a specific target.",
      "params": [
        {
          "name": "wm_learn",
          "bounds": [0, 1]
        }
      ],
      "evidence": "eta = 0.25 * wm_learn * (1.0 + wm_weight)  # a bit more diffusion when WM is relied upon\nw[s, :] = (1.0 - eta) * w[s, :] + eta * w_0[s, :]",
      "expressible_in_slots": true
    }
  ]
}
